 async function api(path:string,method='GET',body?:unknown){const res=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify(body||{})});const data:any=await res.json();const record={time:new Date().toISOString(),method,path,request:safe(body||null),status:res.status,response:safe(data)};evidence.current=[...evidence.current,record].slice(-150);setRecords([...evidence.current]);if(!res.ok)throw Object.assign(new Error(messages[data.error]||data.message||data.error),{status:res.status,data});return data;}
 async function refresh(){const s=await api('/api/auth/session');setAccount(s.accountId||'');if(s.authenticated){const p=await api('/api/private'),k=await api('/api/passkeys');setItems(p.items);setKeys(k.items);setAudit(await api('/api/evidence'));}else{setItems([]);setKeys([]);setAudit(null);}}
 useEffect(()=>{refresh().catch(()=>setNotice('연결하지 못했어요. 잠시 뒤 새로고침해 주세요.'));},[]);
 async function run(work:()=>Promise<void>){setBusy(true);try{await work();}catch(e:any){if(e.name==='NotAllowedError'||e.name==='AbortError')setNotice('패스키 창을 취소했거나 시간이 지났어요. 새 패스키는 저장하지 않았습니다.');else setNotice(e.message||'처리하지 못했어요. 다시 시도해 주세요.');}finally{setBusy(false);}}
 async function register(){await run(async()=>{const q=await api('/api/auth/register/options','POST',{name,provider});try{const response=await startRegistration({optionsJSON:q.options});await api('/api/auth/register/verify','POST',{ticket:q.ticket,response});setNotice('등록했어요. 서버에는 공개키가 저장됐고, 개인 공간이 열렸습니다.');await refresh();setName('내 예비 패스키');}catch(e){await api('/api/auth/cancel','POST',{ticket:q.ticket}).catch(()=>{});throw e;}});}
