 async function logout(){await run(async()=>{await api('/api/auth/logout','POST');setAccount('');setItems([]);setKeys([]);setAudit(null);try{await api('/api/private');setNotice('오류: 로그아웃 뒤 자료가 열렸습니다.');}catch(e:any){setNotice(e.status===401?'로그아웃했어요. 비공개 주소도 401로 거절되는 것을 확인했습니다.':e.message);}});}
