 async function replay(){await run(async()=>{if(!lastLogin.current){setNotice('먼저 로그아웃한 뒤 패스키로 로그인해 주세요. 이 탭에서 성공한 로그인 요청을 재사용합니다.');return;}try{await api('/api/auth/login/verify','POST',lastLogin.current);setNotice('오류: 질문이 재사용됐습니다.');}catch(e:any){setNotice(e.status===403?'통과: 이미 쓴 질문을 재사용한 요청이 403으로 거절됐어요.':e.message);}});}
 async function tamper(){await run(async()=>{const q=await api('/api/auth/login/options','POST');const response=await startAuthentication({optionsJSON:q.options});response.response.signature='AAAA';try{await api('/api/auth/login/verify','POST',{ticket:q.ticket,response});setNotice('오류: 틀린 서명이 통과했습니다.');}catch(e:any){setNotice(e.status===403?'통과: 바꿔 보낸 서명을 서버가 403으로 거절했어요.':e.message);}await refresh();});}
